package org.slavicmyths.quest185;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import org.slavicmyths.yaga.*;
/** Per-player sessions. Scene actors exist only on the recipient client. */
public final class Quest185Sessions {
 public static final UUID NONE=new UUID(0,0);
 static final class Session{UUID token=UUID.randomUUID();String kind;int sequence,page,mask,ritual=-1;long expires,due;String lastCue="";boolean info;BlockPos door;Session(String k,long now){kind=k;expires=now+1200;}}
 private static final Map<UUID,Session> SESSIONS=new HashMap<>();
 private static List<String> lines(Session s){var result=new ArrayList<String>();if(s.kind.equals("eye")){result.add("early.0");result.add("early.1");result.add("early.2");result.add("early.3");if((s.mask&2)!=0)result.add("early.cat");if((s.mask&4)!=0)result.add("early.wolf");}else if(s.kind.equals("earth_reward")){result.add("early.reward");}else if(s.kind.equals("lesson_offer")||s.kind.equals("lesson")){result.add("early.lesson");}else if(s.kind.equals("wolfquest")){result.add("wolf."+s.ritual);}else if(s.kind.equals("intro")){result.add("intro.0");result.add("intro.1");if((s.mask&2)!=0)result.add("intro.cat");if((s.mask&4)!=0)result.add("intro.wolf");result.add("intro.4");result.add("intro.choice");result.add("intro.end");}else if(s.kind.equals("warning")){result.add("warning.yaga");if((s.mask&2)!=0)result.add("warning.cat");if((s.mask&4)!=0)result.add("warning.wolf");}else if(s.kind.equals("ritual")){result.add(s.ritual==0?"q1.claimed":s.ritual==3?"horn.already":"ritual."+s.ritual);if(s.ritual==1&&(s.mask&2)!=0)result.add("ritual.cat");if(s.ritual==2&&(s.mask&4)!=0)result.add("ritual.wolf");if(s.ritual==5)result.add("ritual.end");if(s.ritual==1)result.add("q3.offer");if(s.ritual==2)result.add("q4.offer");}return result;}
 public static void invitation(ServerPlayer p,String speaker){var s=new Session("invite",Quest185Story.now(p));SESSIONS.put(p.getUUID(),s);send(p,s);}
 public static BlockPos door(ServerPlayer p){var n=Quest185Story.data(p);return n.contains("Hut")&&n.getString("HutDimension").equals("minecraft:overworld")?BlockPos.of(n.getLong("Hut")).offset(0,4,-6):null;}
 public static boolean nearYaga(ServerPlayer p){var pos=door(p);boolean close=pos!=null&&pos.distSqr(p.blockPosition())<=16*16||!p.serverLevel().getEntitiesOfClass(BabaYaga.class,p.getBoundingBox().inflate(12),y->y.isAlive()&&p.distanceToSqr(y)<=144).isEmpty();return p.isAlive()&&!p.isSpectator()&&close&&!YagaData.get(p.serverLevel()).progress(p.getUUID()).blocked(Quest185Story.now(p));}
 public static void open(ServerPlayer p,boolean intro){Quest185Story.migrate(p);if(!nearYaga(p)||intro&&p.getZ()>door(p).getZ()-.5){p.displayClientMessage(Quest185Story.text("visit_yaga"),true);journal(p);return;}var s=new Session(intro?"intro":"journal",Quest185Story.now(p));s.door=door(p);s.mask=1|(Quest185Story.metBayun(p)&&Quest185Story.bayunTrust(p)>=2?2:0)|(org.slavicmyths.wolf.WolfProgress.data(p).getBoolean("wolf_met")&&Quest185Story.wolfTrust(p)>=2?4:0);s.page=intro?Math.clamp(Quest185Story.data(p).getInt("IntroPage"),0,lines(s).size()-1):0;SESSIONS.put(p.getUUID(),s);if(intro)Quest185Story.data(p).putBoolean("IntroStarted",true);send(p,s);}
 public static void journal(ServerPlayer p){var s=new Session("journal",Quest185Story.now(p));s.door=door(p);SESSIONS.put(p.getUUID(),s);send(p,s);}
 private static void send(ServerPlayer p,Session s){var n=Quest185Story.snapshot(p);n.putUUID("Token",s.token);n.putString("Kind",s.kind);n.putInt("Sequence",s.sequence);n.putInt("Page",s.page);n.putInt("Mask",s.mask);n.putInt("Ritual",s.ritual);n.putLong("Wait",Math.max(0,s.due-Quest185Story.now(p)));if(s.door!=null)n.putLong("Door",s.door.asLong());var l=lines(s);if(!l.isEmpty()){String line=l.get(Math.clamp(s.page,0,l.size()-1));if(line.equals("intro.0")&&Quest185Story.yagaTrust(p)<2)line="intro.cautious";n.putString("Line","quest185.dialogue."+line);n.putString("Speaker",line.contains("cat")?"bayun":line.contains("wolf")?"wolf":"yaga");n.putBoolean("Last",s.page>=l.size()-1);}if(s.kind.equals("invite"))n.putString("Inviter",Quest185Story.data(p).getString("Inviter"));String cueKey=s.kind+":"+s.page;if(!l.isEmpty()&&!cueKey.equals(s.lastCue)){s.lastCue=cueKey;Quest185Content.sound(p,n.getString("Speaker").equals("bayun")?"bayun_comment":n.getString("Speaker").equals("wolf")?"wolf_comment":"yaga_greeting");}Quest185Network.send(p,n);}
 public static void close(ServerPlayer p){var old=SESSIONS.remove(p.getUUID());if(old==null)return;if(old!=null&&old.kind.equals("intro"))Quest185Story.data(p).putInt("IntroPage",old.page);var n=new CompoundTag();n.putString("Kind","closed");Quest185Network.send(p,n);}
 public static void action(ServerPlayer p,Quest185Network.Action a){long now=Quest185Story.now(p);if(a.action()==0){if(now<p.getPersistentData().getLong("Quest185OpenAt"))return;p.getPersistentData().putLong("Quest185OpenAt",now+10);journal(p);return;}var s=SESSIONS.get(p.getUUID());if(s==null||!Quest185State.admits(s.token,a.token(),s.sequence,a.sequence(),now,s.expires)||!p.isAlive()||p.isSpectator())return;s.sequence++;s.expires=now+1200;
  if(a.action()==9){close(p);return;}
  if(a.action()==2){Quest185Story.data(p).putString("TeleportChoice","walk");journal(p);return;}
  if(a.action()==1){if(Quest185Story.data(p).getBoolean("Invitation"))teleport(p,s);return;}
  if(a.action()==3){if(s.kind.equals("arrival")&&nearYaga(p)){open(p,true);}return;}
  if(a.action()==4){open(p,!Quest185Story.data(p).getBoolean("IntroDone"));return;}
  if(a.action()==10&&nearYaga(p)){s.info=true;var n=Quest185Story.snapshot(p);n.putUUID("Token",s.token);n.putInt("Sequence",s.sequence);n.putString("Kind","info");n.putString("Line","quest185.dialogue.extra.mor");n.putString("Speaker","yaga");Quest185Network.send(p,n);return;}
  if(a.action()==11&&nearYaga(p)){Quest185Story.data(p).putInt("IntroPage",0);open(p,true);return;}
  if(a.action()==12&&nearYaga(p)&&Quest185Story.eyeReady(p)){s.kind="eye";s.page=0;s.due=now+60;s.door=door(p);setMask(p,s);Quest185Content.sound(p,"ritual_sample");send(p,s);return;}
  if(a.action()==13&&nearYaga(p)&&Quest185Story.data(p).getBoolean("Cleansing")&&!Quest185Story.data(p).getBoolean("EarthRestorationRewardClaimed")){var lessons=CleansingLessons.get(p.serverLevel());if(lessons.begin(p)){s.kind=lessons.virtual(p.getUUID())?"lesson_offer":"journal";s.page=0;send(p,s);}return;}
  if(a.action()==14&&nearYaga(p)&&Quest185Story.data(p).getBoolean("Cleansing")&&!Quest185Story.data(p).getBoolean("EarthRestorationRewardClaimed")){var lessons=CleansingLessons.get(p.serverLevel());if(lessons.startVirtual(p)){s.kind="lesson";s.page=0;s.due=now+60;send(p,s);}return;}
  if(a.action()==15&&nearYaga(p)&&Quest185Story.claimEarth(p)){s.kind="earth_reward";s.page=0;s.door=door(p);setMask(p,s);send(p,s);return;}
  if(a.action()==5&&(nearYaga(p)||s.kind.equals("wolfquest")&&wolfNear(p))){if(s.info){s.info=false;send(p,s);return;}var l=lines(s);if(s.kind.equals("eye")){if(s.page==0){if(now<s.due)return;if(!Quest185Story.researchEye(p)){s.kind="journal";send(p,s);return;}}if(s.page<l.size()-1)s.page++;else{s.kind="journal";s.page=0;}}else if(s.kind.equals("lesson")||s.kind.equals("lesson_offer")||s.kind.equals("earth_reward")){if(s.kind.equals("lesson")&&now<s.due)return;s.kind="journal";s.page=0;}else if(s.kind.equals("wolfquest")){s.kind="journal";s.page=0;}else if(s.kind.equals("intro")){if(s.page>=l.size()-1){Quest185Story.data(p).putBoolean("IntroDone",true);Quest185Story.data(p).putBoolean("MetYaga",true);Quest185Story.data(p).putLong("YagaDialogAt",now);s.kind="journal";s.page=0;}else{s.page++;Quest185Story.data(p).putInt("IntroPage",s.page);}}else if(s.kind.equals("warning")){if(s.page>=l.size()-1){Quest185Story.data(p).putBoolean("WarningRead",true);Quest185Story.claim(p,4);s.kind="journal";}else s.page++;}else if(s.kind.equals("ritual")){if(now<s.due)return;if(s.page<l.size()-1)s.page++;else{s.kind="journal";s.page=0;}}send(p,s);return;}
  if(a.action()==6){int i=a.stage();if(i<0||i>=9)return;if(i<6&&!nearYaga(p))return;if(i>=6&&!wolfNear(p))return;if(i>=6&&Quest185Story.status(p,i)==Quest185State.Status.AVAILABLE){var q=Quest185State.quest(Quest185Story.data(p),i);q.putBoolean("Accepted",true);if(i==7)q.putInt("StartKills",Quest185Story.data(p).getInt("BasicKills"));s.kind="wolfquest";s.ritual=i;s.page=0;send(p,s);return;}
   if(i==4&&!Quest185State.done(Quest185Story.data(p),4)){s.kind="warning";s.page=0;s.door=door(p);setMask(p,s);send(p,s);return;}
   if(Quest185Story.claim(p,i)){if(i==0||i==1||i==2||i==3||i==5){s.kind="ritual";s.ritual=i;s.page=0;s.due=now+(i==1?48:i==2?60:i==5?80:0);s.door=door(p);setMask(p,s);Quest185Content.sound(p,"ritual_sample");}send(p,s);}return;}
  if(a.action()==7){Quest185Story.collect(p);send(p,s);return;}
  if(a.action()==8&&nearYaga(p)&&Quest185Story.status(p,6)==Quest185State.Status.ACTIVE&&!Quest185Story.data(p).getBoolean("InfectionKnown")){Quest185Story.data(p).putBoolean("TraceBlock",true);Quest185Content.sound(p,"ritual_sample");send(p,s);}
 }
 private static void setMask(ServerPlayer p,Session s){s.mask=1|(Quest185Story.metBayun(p)&&Quest185Story.bayunTrust(p)>=2?2:0)|(Quest185Story.wolfTrust(p)>=2?4:0);}
 public static boolean wolfNear(ServerPlayer p){return !p.serverLevel().getEntitiesOfClass(org.slavicmyths.wolf.GreyWolf.class,p.getBoundingBox().inflate(12),w->!(w instanceof WolfSupport)&&p.distanceToSqr(w)<=144&&!w.busy()).isEmpty();}
 public static Vec3 safe(ServerPlayer p,BlockPos around,int min,int max){return safe(p,around,min,max,p.getBbWidth(),p.getBbHeight());}
 public static Vec3 safe(ServerPlayer p,BlockPos around,int min,int max,float width,float height){var w=p.serverLevel();for(int distance=min;distance<=max;distance++)for(int dx:new int[]{0,-1,1,-2,2})for(int dy=1;dy>=-6;dy--){var pos=around.offset(dx,dy,-distance);if(!w.hasChunkAt(pos)||!w.hasChunkAt(pos.below())||!w.getWorldBorder().isWithinBounds(pos)||pos.getY()<w.getMinBuildHeight()+1||!w.getFluidState(pos).isEmpty()||!w.getFluidState(pos.below()).isEmpty())continue;var below=w.getBlockState(pos.below());if(!below.isCollisionShapeFullBlock(w,pos.below())||below.is(Blocks.MAGMA_BLOCK)||below.is(Blocks.CAMPFIRE)||below.is(Blocks.CACTUS)||org.slavicmyths.mor.MorBlocks.index(below)>=0)continue;var at=Vec3.atBottomCenterOf(pos);var box=new AABB(at.x-width/2,at.y,at.z-width/2,at.x+width/2,at.y+height,at.z+width/2);if(!w.noCollision(p,box)||!w.getEntitiesOfClass(LivingEntity.class,box.inflate(.25),e->e!=p&&e.isAlive()).isEmpty())continue;return at;}return null;}
 private static void teleport(ServerPlayer p,Session s){if(p.level().dimension()!=Level.OVERWORLD){p.displayClientMessage(Quest185Story.text("overworld_only"),true);return;}if(p.isPassenger()){p.displayClientMessage(Quest185Story.text("dismount"),true);return;}var door=door(p);if(door==null){p.displayClientMessage(Quest185Story.text("hut_unknown"),true);return;}var w=p.serverLevel();w.getChunkAt(door);w.getChunkAt(door.north(5));if(!(w.getBlockState(door).getBlock() instanceof net.minecraft.world.level.block.DoorBlock)){p.displayClientMessage(Quest185Story.text("hut_unavailable"),true);return;}var at=safe(p,door,3,7);if(at==null){p.displayClientMessage(Quest185Story.text("no_safe_ground"),true);return;}Quest185Content.sound(p,"teleport_start");p.getPersistentData().putInt("Quest185FallGrace",60);p.teleportTo(w,at.x,at.y,at.z,0,0);s.kind="arrival";s.door=door;s.expires=Quest185Story.now(p)+200;Quest185Story.data(p).putString("TeleportChoice","teleport");Quest185Content.sound(p,"teleport_end");send(p,s);}
 public static void tick(ServerPlayer p){var s=SESSIONS.get(p.getUUID());if(s!=null&&(Quest185Story.now(p)>s.expires||!p.isAlive()||!s.kind.equals("invite")&&!s.kind.equals("journal")&&!s.kind.equals("arrival")&&!(s.kind.equals("wolfquest")?wolfNear(p):nearYaga(p))))close(p);}
 public static void logout(UUID id){SESSIONS.remove(id);}
 private Quest185Sessions(){}
}
